CREATE OR REPLACE FUNCTION public.pass4p_document_present(_ws uuid,_kind text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.provider_credentials c JOIN storage.objects o ON o.bucket_id='provider-docs' AND o.name=c.doc_path JOIN storage.buckets b ON b.id=o.bucket_id AND NOT b.public JOIN public.workspace_members m ON m.user_id=c.provider_user_id AND m.workspace_id=c.workspace_id AND m.role='owner' AND NOT m.is_contractor AND m.removed_at IS NULL WHERE c.workspace_id=_ws AND c.kind=_kind AND c.accuracy_attested_at IS NOT NULL AND c.lifecycle_state IN ('current','active') AND (c.effective_at IS NULL OR c.effective_at<=current_date) AND (c.expires_at IS NULL OR c.expires_at>=current_date) AND (_kind='w9' OR (c.effective_at IS NOT NULL AND c.expires_at IS NOT NULL)) AND c.doc_path LIKE 'credentials/'||c.provider_user_id::text||'/%' AND (_kind<>'auto_insurance' OR (nullif(c.insurance_carrier,'') IS NOT NULL AND nullif(c.policy_reference,'') IS NOT NULL AND c.coverage_cents>0))) $$;
CREATE OR REPLACE FUNCTION public.pass4p_service_eligible(_ws uuid,_service text,_vehicle uuid DEFAULT NULL) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.workspaces w WHERE w.id=_ws AND w.status='active' AND NOT w.is_test_account AND EXISTS(SELECT 1 FROM public.vehicles v WHERE v.workspace_id=w.id AND (_vehicle IS NULL OR v.id=_vehicle) AND public.pass4p_vehicle_complete(v.id) AND lower(_service)=ANY(v.service_capabilities) AND (w.provider_subtype='nemt_business' OR (lower(_service)='ambulatory' AND v.vehicle_category='ambulatory' AND v.evidence_status='satisfied')))
 AND (w.provider_subtype='nemt_business' OR (lower(_service)='ambulatory' AND w.provider_verified AND NOT EXISTS(SELECT 1 FROM unnest(ARRAY['driver_license','auto_insurance','w9']) k WHERE NOT public.pass4p_document_present(w.id,k)) AND NOT EXISTS(SELECT 1 FROM public.provider_credentials c WHERE c.workspace_id=w.id AND c.required AND (c.doc_path IS NULL OR c.lifecycle_state IN ('expired','removed','failed') OR c.expires_at<current_date))))) $$;
CREATE FUNCTION public.pass4p_driver_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF EXISTS(SELECT 1 FROM public.workspaces WHERE id=NEW.workspace_id AND provider_subtype='independent_contractor') AND EXISTS(SELECT 1 FROM unnest(NEW.service_capabilities) s WHERE lower(s)<>'ambulatory') THEN RAISE EXCEPTION 'Independent Contractor driver supports Ambulatory only'; END IF; RETURN NEW; END $$;
CREATE TRIGGER pass4p_driver_guard BEFORE INSERT OR UPDATE ON public.drivers FOR EACH ROW EXECUTE FUNCTION public.pass4p_driver_guard();